let runtime

/**
 * Active sessions, mapped by multiplayer session ids
 */
const sessions = new Map()

/**
 * Active connections, mapping comms session to multiplayer session
 */
const connections = new Map()

/**
 * Node-level locks: nodeId -> { session, user, acquiredAt, timeoutHandle }
 */
const nodeLocks = new Map()

const LOCK_TIMEOUT_MS = 5 * 60 * 1000 // 5 minutes
const BATON_PASS_TIMEOUT_MS = 10 * 1000 // 10 seconds

let baton = null            // { session (mp ID), user, grantedAt } or null
let batonPassTimeout = null
let batonPassRequester = null // { commsSession, sessionId }

let liveSync


function getSessionsList() {
    return Array.from(sessions.values()).filter(session => session.active)
}

/**
 * Find the comms session (websocket id) for a given multiplayer session id.
 */
function findCommsSession(mpSessionId) {
    for (const [commsSession, sessionId] of connections.entries()) {
        if (sessionId === mpSessionId) {
            return commsSession
        }
    }
    return null
}

/**
 * Grant the baton to a specific multiplayer session.
 * Clears any pending pass timeout and broadcasts the new state.
 */
function grantBaton(mpSessionId) {
    if (batonPassTimeout) {
        clearTimeout(batonPassTimeout)
        batonPassTimeout = null
    }
    batonPassRequester = null

    const session = sessions.get(mpSessionId)
    baton = {
        session: mpSessionId,
        user: session ? session.user : null,
        grantedAt: Date.now()
    }

    // Send targeted grant to the new holder
    const commsSession = findCommsSession(mpSessionId)
    if (commsSession) {
        runtime.events.emit('comms', {
            topic: 'multiplayer/baton-granted',
            data: { session: baton.session, user: baton.user },
            session: commsSession
        })
    }

    // Broadcast baton state to all
    runtime.events.emit('comms', {
        topic: 'multiplayer/baton-state',
        data: { holder: { session: baton.session, user: baton.user } }
    })

    runtime.log.trace('multiplayer baton granted to session:' + mpSessionId)
}

module.exports = {
    init: function(_runtime) {
        runtime = _runtime
        runtime.events.on('comms:connection-removed', (opts) => {
            const existingSessionId = connections.get(opts.session)
            if (existingSessionId) {
                connections.delete(opts.session)

                // Release all locks held by this session
                for (const [nodeId, lock] of nodeLocks.entries()) {
                    if (lock.session === existingSessionId) {
                        clearTimeout(lock.timeoutHandle)
                        nodeLocks.delete(nodeId)
                        runtime.events.emit('comms', {
                            topic: 'multiplayer/lock-changed',
                            data: { nodeId: nodeId, locked: false, session: existingSessionId, reason: 'disconnect' }
                        })
                    }
                }

                // Release baton if held by this session
                if (baton && baton.session === existingSessionId) {
                    baton = null
                    if (batonPassTimeout) {
                        clearTimeout(batonPassTimeout)
                        batonPassTimeout = null
                    }
                    runtime.log.trace('multiplayer baton released (disconnect) session:' + existingSessionId)
                    if (batonPassRequester) {
                        // Grant to the pending requester
                        grantBaton(batonPassRequester.sessionId)
                    } else {
                        runtime.events.emit('comms', {
                            topic: 'multiplayer/baton-state',
                            data: { holder: null }
                        })
                    }
                }
                // If the disconnected session was the pending requester, clear it
                if (batonPassRequester && batonPassRequester.sessionId === existingSessionId) {
                    batonPassRequester = null
                }

                const session = sessions.get(existingSessionId)
                if (session) {
                    session.active = false
                    session.idleTimeout = setTimeout(() => {
                        sessions.delete(existingSessionId)
                    }, 30000)
                    runtime.events.emit('comms', {
                        topic: "multiplayer/connection-removed",
                        data: { session: existingSessionId }
                    })
                }
            }
        })
        runtime.events.on('comms:message:multiplayer/connect', (opts) => {
            let session
            if (!sessions.has(opts.data.session)) {
                // Brand new session
                let user = opts.user
                if (!user || user.anonymous) {
                    user = user || { anonymous: true }
                    user.username = `Anon ${Math.floor(Math.random()*100)}`
                }
                session = {
                    session: opts.data.session,
                    user,
                    active: true
                }
                sessions.set(opts.data.session, session)
                connections.set(opts.session, opts.data.session)
                runtime.log.trace(`multiplayer new session:${opts.data.session} user:${user.username}`)
            } else {
                // Reconnected connection - keep existing state
                connections.set(opts.session, opts.data.session)
                // const existingConnection  = connections.get(opts.data.session)
                session = sessions.get(opts.data.session)
                session.active = true
                runtime.log.trace(`multiplayer reconnected session:${opts.data.session} user:${session.user.username}`)
                clearTimeout(session.idleTimeout)
            }
            // Auto-grant baton if nobody holds it
            if (!baton) {
                grantBaton(session.session)
            }

            // Tell existing sessions about the new connection
            runtime.events.emit('comms', {
                topic: "multiplayer/connection-added",
                excludeSession: opts.session,
                data: session
            })

            // Send init info to new connection
            const initPacket = {
                topic: "multiplayer/init",
                data: {
                    sessions: getSessionsList(),
                    baton: baton ? { session: baton.session, user: baton.user } : null
                },
                session: opts.session
            }
            // console.log('<<', initPacket)
            runtime.events.emit('comms', initPacket)
        })
        runtime.events.on('comms:message:multiplayer/disconnect', (opts) => {
            const existingSessionId = connections.get(opts.session)
            connections.delete(opts.session)
            sessions.delete(existingSessionId)

            // Release baton if held by disconnecting session
            if (baton && baton.session === existingSessionId) {
                baton = null
                if (batonPassTimeout) {
                    clearTimeout(batonPassTimeout)
                    batonPassTimeout = null
                }
                if (batonPassRequester) {
                    grantBaton(batonPassRequester.sessionId)
                } else {
                    runtime.events.emit('comms', {
                        topic: 'multiplayer/baton-state',
                        data: { holder: null }
                    })
                }
            }
            if (batonPassRequester && batonPassRequester.sessionId === existingSessionId) {
                batonPassRequester = null
            }

            runtime.events.emit('comms', {
                topic: "multiplayer/connection-removed",
                data: { session: existingSessionId, disconnected: true }
            })
        })
        // --- Node Locking ---
        runtime.events.on('comms:message:multiplayer/lock-request', (opts) => {
            const sessionId = connections.get(opts.session)
            const nodeId = opts.data && opts.data.nodeId
            const action = opts.data && opts.data.action // 'acquire' or 'release'

            if (!sessionId || !nodeId) return

            if (action === 'release') {
                const lock = nodeLocks.get(nodeId)
                if (lock && lock.session === sessionId) {
                    clearTimeout(lock.timeoutHandle)
                    nodeLocks.delete(nodeId)
                    runtime.events.emit('comms', {
                        topic: 'multiplayer/lock-changed',
                        data: { nodeId: nodeId, locked: false, session: sessionId }
                    })
                }
                return
            }

            // Default: acquire
            const existingLock = nodeLocks.get(nodeId)
            if (existingLock && existingLock.session !== sessionId) {
                // Lock held by another session
                const holder = sessions.get(existingLock.session)
                runtime.events.emit('comms', {
                    topic: 'multiplayer/lock-denied',
                    data: {
                        nodeId: nodeId,
                        holder: {
                            session: existingLock.session,
                            user: holder ? holder.user : null
                        }
                    },
                    session: opts.session
                })
                return
            }

            // Grant lock (new or refresh)
            if (existingLock) {
                clearTimeout(existingLock.timeoutHandle)
            }
            const timeoutHandle = setTimeout(() => {
                nodeLocks.delete(nodeId)
                runtime.events.emit('comms', {
                    topic: 'multiplayer/lock-changed',
                    data: { nodeId: nodeId, locked: false, session: sessionId, reason: 'timeout' }
                })
            }, LOCK_TIMEOUT_MS)

            nodeLocks.set(nodeId, {
                session: sessionId,
                user: sessions.get(sessionId) ? sessions.get(sessionId).user : null,
                acquiredAt: Date.now(),
                timeoutHandle: timeoutHandle
            })

            // Send grant to requester
            runtime.events.emit('comms', {
                topic: 'multiplayer/lock-granted',
                data: { nodeId: nodeId },
                session: opts.session
            })

            // Broadcast lock state to all others
            runtime.events.emit('comms', {
                topic: 'multiplayer/lock-changed',
                data: {
                    nodeId: nodeId,
                    locked: true,
                    session: sessionId,
                    user: sessions.get(sessionId) ? sessions.get(sessionId).user : null
                },
                excludeSession: opts.session
            })
        })

        runtime.events.on('comms:message:multiplayer/lock-heartbeat', (opts) => {
            const sessionId = connections.get(opts.session)
            const nodeId = opts.data && opts.data.nodeId
            if (!sessionId || !nodeId) return

            const lock = nodeLocks.get(nodeId)
            if (lock && lock.session === sessionId) {
                clearTimeout(lock.timeoutHandle)
                lock.timeoutHandle = setTimeout(() => {
                    nodeLocks.delete(nodeId)
                    runtime.events.emit('comms', {
                        topic: 'multiplayer/lock-changed',
                        data: { nodeId: nodeId, locked: false, session: sessionId, reason: 'timeout' }
                    })
                }, LOCK_TIMEOUT_MS)
            }
        })

        // --- Baton (merge-master) ---
        runtime.events.on('comms:message:multiplayer/baton-request', (opts) => {
            const sessionId = connections.get(opts.session)
            if (!sessionId) return

            const action = opts.data && opts.data.action

            if (action === 'release') {
                // Holder voluntarily releases the baton
                if (baton && baton.session === sessionId) {
                    baton = null
                    if (batonPassTimeout) {
                        clearTimeout(batonPassTimeout)
                        batonPassTimeout = null
                    }
                    batonPassRequester = null
                    runtime.events.emit('comms', {
                        topic: 'multiplayer/baton-state',
                        data: { holder: null }
                    })
                    runtime.log.trace('multiplayer baton released by session:' + sessionId)
                }
                return
            }

            if (action === 'pass') {
                // Holder explicitly passes to a target session
                var target = opts.data && opts.data.target
                if (baton && baton.session === sessionId && target && sessions.has(target)) {
                    grantBaton(target)
                }
                return
            }

            // Default: request
            if (!baton) {
                // No holder — grant immediately
                grantBaton(sessionId)
            } else if (baton.session === sessionId) {
                // Already holds it — no-op
            } else {
                // Someone else holds the baton — send pass-request to holder
                var holderComms = findCommsSession(baton.session)
                batonPassRequester = { commsSession: opts.session, sessionId: sessionId }

                if (holderComms) {
                    var requesterSession = sessions.get(sessionId)
                    runtime.events.emit('comms', {
                        topic: 'multiplayer/baton-pass-request',
                        data: {
                            requester: {
                                session: sessionId,
                                user: requesterSession ? requesterSession.user : null
                            }
                        },
                        session: holderComms
                    })
                }

                // Start timeout — auto-transfer after 10s
                if (batonPassTimeout) {
                    clearTimeout(batonPassTimeout)
                }
                batonPassTimeout = setTimeout(() => {
                    if (batonPassRequester && batonPassRequester.sessionId === sessionId) {
                        grantBaton(sessionId)
                    }
                }, BATON_PASS_TIMEOUT_MS)
            }
        })

        // Initialize liveSync module
        liveSync = require('./liveSync')
        liveSync.init(runtime, {
            getBatonHolder: function() { return baton ? baton.session : null },
            getBatonHolderComms: function() { return baton ? findCommsSession(baton.session) : null },
            getSessionForComms: function(commsSession) { return connections.get(commsSession) }
        })

        runtime.events.on('comms:message:multiplayer/location', (opts) => {
            // console.log('>>>', opts.user, opts.data)

            const sessionId = connections.get(opts.session)
            const session = sessions.get(sessionId)

            if (session) {
                if (opts.user) {
                    if (session.user.anonymous !== opts.user.anonymous) {
                        session.user = opts.user
                        runtime.events.emit('comms', {
                            topic: 'multiplayer/connection-added',
                            excludeSession: opts.session,
                            data: session
                        })
                    }
                }

                session.location = opts.data

                const payload = {
                    session: sessionId,
                    workspace: opts.data.workspace,
                    node: opts.data.node,
                    cursor: opts.data.cursor
                }
                runtime.events.emit('comms', {
                    topic: 'multiplayer/location',
                    data: payload,
                    excludeSession: opts.session
                })
            }
        })
    }
}